mapper.select:
SELECT a.*, b.username FROM visual_screen.vs_scheme_info a LEFT JOIN visual_screen.sys_user b on a.add_user = b.id where 1=1
and a.id = #{params.id}
AND a.name like concat(concat('%',#{params.name}),'%')
and a.add_user = #{params.add_user}
ORDER BY a.add_time desc LIMIT #{params.rows,jdbcType=INTEGER} OFFSET #{params.page,jdbcType=INTEGER}

SELECT COUNT(*) FROM visual_screen.vs_scheme_info a where 1=1
and a.id = #{params.id}
AND a.name like concat(concat('%',#{params.name}),'%')
and a.add_user = #{params.add_user}

SELECT a.* FROM visual_screen.vs_scheme_info a where 1=1
and a.id = #{params.id}
AND a.name like concat(concat('%',#{params.name}),'%')
and a.add_user = #{params.add_user}
ORDER BY a.add_time desc

SELECT
*
FROM visual_screen.vs_scheme_info a
where 1=1

    and a.name = #{params.name}


    and a.id != #{params.id}

mapper.update:
UPDATE visual_screen.vs_scheme_info SET

    name = #{params.name},


    rotation_interval = #{params.rotation_interval},

id = #{params.id}
WHERE id = #{params.id}

mapper.select:
SELECT a.* FROM visual_screen.vs_scheme_page_rel a where 1=1
and a.scheme_id = #{params.scheme_id}
and a.page_id = #{params.page_id}
ORDER BY CAST(a.sort AS NUMERIC) asc

mapper.delete:
DELETE
FROM
visual_screen.vs_scheme_page_rel
WHERE 1 = 1

    AND scheme_id = #{params.scheme_id}


    AND page_id = #{params.page_id}
